parameters.jsCode:
const body = $input.first().json.body;
const owner = body.owner || 'facebook';
const repo = body.repo || 'react';
const pullNumber = body.pullNumber || 1;
const githubToken = body.githubToken;
const reviewSummary = body.reviewSummary || 'AI Code Review Summary';
const issues = body.issues || [];

let markdownComment = `### 🤖 AI-Powered Code Reviewer Report\n\n`;
markdownComment += `**Điểm chất lượng:** ${body.qualityScore || 85}/100 (Hạng: ${body.grade || 'B'})\n\n`;
markdownComment += `> ${reviewSummary}\n\n`;

if (issues.length > 0) {
  markdownComment += `#### 🔍 Chi tiết vấn đề phát hiện:\n\n`;
  issues.forEach((iss, idx) => {
    markdownComment += `* **[${iss.severity || 'WARNING'}] Dòng ${iss.line || 'N/A'}**: ${iss.message}\n`;
    if (iss.suggestion) markdownComment += `  - 💡 *Đề xuất*: ${iss.suggestion}\n`;
  });
} else {
  markdownComment += `✅ **Mã nguồn sạch! Không phát hiện lỗ hổng nghiêm trọng.**\n`;
}

return {
  json: {
    url: `https://api.github.com/repos/${owner}/${repo}/issues/${pullNumber}/comments`,
    authHeader: `Bearer ${githubToken}`,
    bodyPayload: { body: markdownComment }
  }
};

parameters.responseBody:
={
  "success": true,
  "message": "Đã post comment nhận xét thành công lên GitHub PR!"
}
